(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7335],{48231:function(a,e,r){Promise.resolve().then(r.bind(r,68326))},68326:function(a,e,r){"use strict";r.r(e),r.d(e,{default:function(){return t}});var i=r(3827);r(64090);var n=r(31725);let l={updatedAt:"2026-06-16",articleHeadline:"Amazon T\xfcrkiye K\xe2r Hesaplama: Referral Komisyonu, KDV ve Stopaj Dahil Net K\xe2r Rehberi",articleDescription:"Amazon T\xfcrkiye satıcıları i\xe7in referral komisyonu, kargo, KDV ve stopaj dahil net k\xe2r hesaplama rehberi; ayrı platform hizmet bedeli olmamasının avantajı ve adım adım işlenmiş \xf6rnek.",blocks:[{type:"prose",heading:"Amazon T\xfcrkiye’de Net K\xe2r Nasıl Hesaplanır?",paragraphs:["Amazon T\xfcrkiye’nin diğer pazaryerlerinden en \xf6nemli farkı, ayrı bir platform hizmet bedeli (PHB) olmamasıdır. Trendyol veya Hepsiburada’da her siparişten sabit bir kesinti yapılırken, Amazon yalnızca kategoriye g\xf6re değişen bir referral (komisyon) \xfccreti alır. Bu komisyon, platformun t\xfcm hizmet bedellerini kapsar.","Bu yapı \xf6zellikle d\xfcş\xfck fiyatlı \xfcr\xfcnlerde \xf6nemli bir fark yaratır: sabit PHB’nin olmaması, 50–100 TL bandındaki \xfcr\xfcnlerde marjı korur. Buna karşılık Amazon’un komisyon oranları bazı kategorilerde %45’e kadar \xe7ıkabildiği i\xe7in, y\xfcksek komisyonlu kategorilerde net k\xe2r hızla erir. Bu y\xfczden Amazon’da her \xfcr\xfcn\xfc ayrı ayrı hesaplamak şarttır."]},{type:"feeTable",heading:"Amazon T\xfcrkiye Kesinti Kalemleri (2026)",intro:"Amazon’da ana kesinti referral komisyonudur; ayrı bir platform hizmet bedeli yoktur. Komisyon oranı kategoriye g\xf6re geniş bir aralıkta değişir.",columns:["Kalem","Oran / Tutar","A\xe7ıklama"],rows:[["Komisyon (referral fee)","Kategoriye g\xf6re %5 – %45","Satış tutarı \xfczerinden; platform hizmet bedellerini de kapsar."],["Komisyon KDV’si","%20 (sabit)","Referral komisyonu %20 KDV’ye tabi bir hizmet bedelidir; bu komisyon KDV’si \xf6denecek KDV’nizden d\xfcş\xfcl\xfcr (indirilir) — net k\xe2ra etkisi br\xfct komisyon kadar değildir."],["Platform Hizmet Bedeli","Yok","Amazon’da Trendyol/Hepsiburada gibi ayrı bir sabit PHB yoktur; referral komisyonu bunu i\xe7erir."],["Kargo","Desiye / g\xf6nderim modeline g\xf6re","Kendi kargonuz veya Amazon lojistiği (FBA) kullanımına g\xf6re değişir."],["Satış KDV’si","\xdcr\xfcn\xfcn ger\xe7ek oranı","Satış fiyatına dahildir; \xfcr\xfcn\xfcn kendi KDV oranından hesaplanır."],["Stopaj","%1","KDV hari\xe7 satış tutarının %1’i; gelir vergisi peşin kesintisi."]],note:"Komisyon oranı kategoriye g\xf6re %5 ile %45 arasında geniş bir bantta değişir. Kendi \xfcr\xfcn\xfcn\xfcz\xfcn kesin oranı i\xe7in yukarıdaki hesaplayıcıyı kullanın."},(0,r(77067).w)({platform:"amazon",heading:"\xd6rnek: 349 TL’lik \xdcr\xfcnde Adım Adım Net K\xe2r",intro:"Aşağıdaki \xf6rnek %15 referral komisyonu, 95 TL \xfcr\xfcn maliyeti ve 15 TL kargo varsayımıyladır. Amazon’da ayrı platform hizmet bedeli olmadığı i\xe7in bu satır g\xf6r\xfcnmez.",salePrice:349,commissionRate:15,cost:95,cargoPrice:15,vatRate:20}),{type:"pitfalls",heading:"Amazon’da K\xe2rınızı Yiyen Kalemler",intro:"Amazon’da PHB olmaması rahatlatıcı g\xf6r\xfcnse de aşağıdaki kalemler atlandığında \xfcr\xfcn k\xe2rlı sanılıp zarar edilebilir.",items:[{title:"Y\xfcksek komisyonlu kategorileri hesaba katmamak",body:"Amazon komisyonu bazı kategorilerde %45’e kadar \xe7ıkar. “PHB yok” avantajı, y\xfcksek komisyonlu bir kategoride kolayca kaybolur."},{title:"FBA (Amazon lojistiği) \xfccretlerini unutmak",body:"Amazon’un kendi lojistiğini kullanıyorsanız depolama ve g\xf6nderim \xfccretleri kargo maliyetinizin \xfcst\xfcne biner. Kendi kargonuzla satıyorsanız bu kalem yoktur."},{title:"Komisyonun KDV etkisini atlamak",body:"Referral komisyonu %20 KDV’ye tabidir; panel bu komisyon KDV’sini hesaplayıp \xf6denecek KDV’den d\xfcşer. Komisyonun KDV etkisini g\xf6z ardı etmek net k\xe2rı yanlış g\xf6sterir."},{title:"Stopajı atlamak",body:"Diğer pazaryerlerinde olduğu gibi Amazon’da da KDV hari\xe7 satışın %1’i stopaj olarak kesilir."},{title:"D\xfcş\xfck KDV’li \xfcr\xfcnde %20 varsaymak",body:"Satış ve maliyet KDV’si \xfcr\xfcn\xfcn ger\xe7ek oranındandır. %1 veya %10 KDV’li \xfcr\xfcnlerde “her şey %20” varsaymak \xf6denecek KDV’yi yanlış hesaplatır."}]},{type:"prose",heading:"Referral Komisyonu, KDV ve Stopajın Teknik Detayı",paragraphs:["Amazon’un referral komisyonu, satış tutarı \xfczerinden alınan ve platformun t\xfcm hizmet maliyetlerini kapsayan tek kalemdir. Bu y\xfczden Amazon’da “komisyon + PHB” diye iki ayrı kesinti aramayın; komisyonun kendisi platform bedelini i\xe7erir. Komisyonun \xfczerine, hizmet bedeli niteliğinde olduğu i\xe7in sabit %20 KDV uygulanır.","Satış KDV’si, maliyet KDV’si ve stopaj matrahı \xfcr\xfcn\xfcn ger\xe7ek KDV oranından hesaplanır; komisyon KDV’si ise her zaman %20’dir. \xd6denecek KDV, satış KDV’nizden indirebileceğiniz gider KDV’lerinin (komisyon ve \xfcr\xfcn maliyeti) d\xfcş\xfclmesiyle bulunur.","Stopaj, gelir vergisinin kaynakta peşin kesilmesidir ve matrahı KDV hari\xe7 satış tutarıdır: 349 TL’lik bir satışta (KDV %20 ise) stopaj = 349 / 1,20 \xd7 0,01 ≈ 2,91 TL olur. Bu tutar yıl sonunda gelir vergisi beyannamenizde mahsup edilir."]},{type:"comparison",heading:"Amazon’u Diğer Pazaryerleriyle Karşılaştırın",intro:"Aynı \xfcr\xfcn\xfc birden fazla pazaryerinde satıyorsanız kesinti yapısı tamamen değişir. Her platformun k\xe2r hesaplayıcısıyla net k\xe2rınızı ayrı g\xf6r\xfcn.",rows:[{platform:"Trendyol",note:"Sabit platform hizmet bedeli kesilir (5,99 veya 13,19 TL); komisyon ayrı.",href:"/trendyol-kar-hesaplama"},{platform:"Hepsiburada",note:"Sabit Marketplace HB + işlem bedeli (toplam 11,40 TL) kesilir.",href:"/hepsiburada-kar-hesaplama"},{platform:"N11",note:"Y\xfczde bazlı pazarlama + pazaryeri hizmet bedeli; sabit PHB yok.",href:"/n11-kar-hesaplama"}]}]},o={platform:"amazon",name:"Amazon T\xfcrkiye",slug:"amazon-turkiye-kar-hesaplama",color:"#ff9900",heroSubtitle:"Amazon T\xfcrkiye'de ayrı platform hizmet bedeli yoktur. Komisyon, kargo, KDV ve stopaj dahil net k\xe2rınızı anında hesaplayın.",ctaText:"Amazon T\xfcrkiye mağazanızı bağlayın, sipariş ve finansal verilerinizi otomatik analiz edin.",formulaLines:(0,i.jsxs)(i.Fragment,{children:["Net K\xe2r = Satış Tutarı",(0,i.jsx)("br",{}),"\xa0\xa0- Komisyon (Referral Fee)",(0,i.jsx)("br",{}),"\xa0\xa0- Kargo Maliyeti",(0,i.jsx)("br",{}),"\xa0\xa0- \xdcr\xfcn Maliyeti (Tedarik + Ambalaj)",(0,i.jsx)("br",{}),"\xa0\xa0- \xd6denecek KDV (Satış KDV - Gider KDV'leri)",(0,i.jsx)("br",{}),"\xa0\xa0- Stopaj (Satış / 1.20 \xd7 0.01)"]}),formulaNote:(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("strong",{style:{color:"inherit"},children:"\xd6nemli:"})," Amazon T\xfcrkiye'de Trendyol veya Hepsiburada'daki gibi ayrı bir platform hizmet bedeli yoktur — komisyon (referral fee) t\xfcm platform bedellerini i\xe7erir. Satış ve maliyet KDV'si \xfcr\xfcn\xfcn ger\xe7ek KDV oranı \xfczerinden, komisyon KDV'si ise %20 \xfczerinden hesaplanır."]}),faq:[{q:"Amazon T\xfcrkiye k\xe2r hesaplama nasıl yapılır?",a:"Amazon T\xfcrkiye'de k\xe2r hesaplamak i\xe7in satış fiyatından komisyon (referral fee), kargo maliyeti, \xfcr\xfcn maliyeti, KDV ve stopaj d\xfcş\xfclmelidir. Amazon'da ayrı bir platform hizmet bedeli (PHB) yoktur — komisyon oranı t\xfcm platform bedellerini i\xe7erir."},{q:"Amazon T\xfcrkiye komisyon oranları ne kadar?",a:"Amazon T\xfcrkiye komisyon oranları (referral fee) kategoriye g\xf6re %5 ile %45 arasında değişir. Kitaplarda %15, elektronik aksesuarlarda %12, giyimde %17 civarındadır. Amazon'un komisyon oranı platform hizmet bedelini de i\xe7erir."},{q:"Amazon'da platform hizmet bedeli var mı?",a:"Hayır, Amazon T\xfcrkiye'de Trendyol veya Hepsiburada'daki gibi ayrı bir platform hizmet bedeli (PHB) yoktur. Amazon'un aldığı komisyon (referral fee) t\xfcm platform hizmet bedellerini kapsar."},{q:"Amazon T\xfcrkiye stopaj oranı ne kadar?",a:"Amazon T\xfcrkiye stopaj oranı KDV hari\xe7 satış tutarının %1'idir. Form\xfcl: Stopaj = Satış / 1,20 \xd7 0,01. Diğer pazaryerleriyle aynı oranı uygular."},{q:"Amazon FBA nedir?",a:"Amazon FBA (Fulfillment by Amazon) programında \xfcr\xfcnlerinizi Amazon deposuna g\xf6nderirsiniz. Sipariş geldiğinde Amazon paketleme ve kargolama işlemini yapar. Bu hizmete ek \xfccret \xf6denir."},{q:"Amazon T\xfcrkiye'nin avantajı ne?",a:"Amazon T\xfcrkiye'de ayrı platform hizmet bedeli yoktur, bu da \xf6zellikle d\xfcş\xfck fiyatlı \xfcr\xfcnlerde maliyet avantajı sağlar. Trendyol'da 8-13 ₺ sabit PHB kesilirken, Amazon'da bu kalem yoktur."},{q:"Amazon ve Trendyol k\xe2r karşılaştırması?",a:"Amazon'da PHB olmadığı i\xe7in d\xfcş\xfck fiyatlı \xfcr\xfcnlerde k\xe2r marjı genellikle daha y\xfcksektir. Ancak komisyon oranları kategoriye g\xf6re değiştiğinden, her \xfcr\xfcn i\xe7in ayrı hesaplama yapılmalıdır."},{q:"NİTRU ile Amazon mağazamı y\xf6netebilir miyim?",a:"Evet, NİTRU Amazon T\xfcrkiye dahil 6 pazaryerini destekler. Amazon SP-API entegrasyonu ile \xfcr\xfcnler, siparişler, iadeler ve finansal verilerinizi tek panelden y\xf6netebilirsiniz."}],blogLinks:[{href:"/blog/eticaret-kdv-stopaj-rehberi",label:"KDV ve Stopaj Rehberi"},{href:"/blog",label:"T\xfcm Blog Yazıları"}],content:l};function t(){return(0,i.jsx)(n.Z,{config:o})}}},function(a){a.O(0,[6669,5250,2406,6095,3897,9778,9952,7774,6676,9419,581,6972,8214,7447,3138,2971,8069,1744],function(){return a(a.s=48231)}),_N_E=a.O()}]);